(function(){"use strict";document.addEventListener("click",i=>{var s;const e=i.target.closest("a");if(!e)return;const t=e.href;if(!t||t.startsWith("javascript:")||t.startsWith("#")||t===window.location.href||t.startsWith("chrome://")||t.startsWith("chrome-extension://")||t.startsWith("about:"))return;const r=(((s=e.textContent)==null?void 0:s.trim())||e.title||e.getAttribute("aria-label")||document.title||t).slice(0,200);chrome.runtime.sendMessage({type:"LINK_CLICKED",url:t,title:r}).catch(()=>{setTimeout(()=>{chrome.runtime.sendMessage({type:"LINK_CLICKED",url:t,title:r}).catch(()=>{})},500)})},!0)})();
